// Console helpers. PROVIDED: do not edit this file in Week 10.
use std::io::{self, Write};

// Print a prompt, read one line, return it trimmed.
// If input is closed (Ctrl-D), exit the program cleanly.
pub fn prompt(message: &str) -> String {
    print!("{message}");
    io::stdout().flush().expect("could not flush stdout");
    let mut line = String::new();
    let bytes = io::stdin()
        .read_line(&mut line)
        .expect("could not read input");
    if bytes == 0 {
        println!();
        println!("Input closed. Goodbye.");
        std::process::exit(0);
    }
    line.trim().to_string()
}

// Show a numbered menu. Returns the chosen number, 1-based.
pub fn menu_choice(title: &str, options: &[String]) -> usize {
    loop {
        println!("{title}");
        for i in 0..options.len() {
            println!("  {}. {}", i + 1, options[i]);
        }
        match prompt("> ").parse::<usize>() {
            Ok(n) => {
                if n >= 1 && n <= options.len() {
                    return n;
                }
                println!("Pick a number from 1 to {}.", options.len());
            }
            Err(_) => println!("Pick a number from 1 to {}.", options.len()),
        }
    }
}
